    internal static Geometry Outline(string name, double size)
    {
        var outline = Geometry.Parse(Paths[name]).Clone();
        outline.Transform = new MatrixTransform(size / 960, 0, 0, size / 960, 0, size);
        outline.Freeze();
        return outline;
    }

    internal static Path Shape(string name, double size, FrameworkElement text)
    {
        var shape = new Path { Data = Outline(name, size), Width = size, Height = size, Tag = name };
        shape.SetBinding(System.Windows.Shapes.Shape.FillProperty, new Binding(text is System.Windows.Controls.Control ? "Foreground" : "(TextElement.Foreground)") { Source = text });
        return shape;
    }

    internal static Wpf.Ui.Controls.ImageIcon Icon(string name, Brush brush, double size = 20)
    {
        var drawing = new DrawingGroup();
        drawing.Children.Add(new GeometryDrawing(Brushes.Transparent, null, new RectangleGeometry(new Rect(0, 0, size, size))));
        drawing.Children.Add(new GeometryDrawing(brush, null, Outline(name, size)));
        var image = new DrawingImage(drawing);
        image.Freeze();
        return new() { Source = image, Width = size, Height = size, Tag = name };
    }
